"use client";

import { useEffect } from "react";
import { createPortal } from "react-dom";
import styles from "./Modal.module.scss";
import Card from "../components/flexBox/Card";
import Text from "../components/text/Text";
import Gutter from "../components/flexBox/Gutter";
import CustomImage from "../components/images/CustomImage";

interface VideoModalProps {
  title?: string;
  src?: string;
  isOpen: boolean;
  onClose: () => void;
  blurb?: string;
  description?: string;
  year?: string;
  stills?: string[];
}

export default function VideoModal({
  title,
  src,
  isOpen,
  onClose,
  blurb,
  description,
  year,
  stills,
}: VideoModalProps) {
  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    if (isOpen) window.addEventListener("keydown", handleKey);
    return () => window.removeEventListener("keydown", handleKey);
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  return createPortal(
    <div className={styles.backdrop} onClick={onClose}>
      <Card backgroundColor={0} radius={0}>
        <Card
          flexDirection="row"
          justifyContent="space-between"
          alignItems="center"
          fit="fill"
          size={0}
        >
          <Card size={10}>
            <Text size={60} color={3} weight={700} fontFamily={2}>
              {title ?? "Video Demo"}
            </Text>
            <Text size={40} color={2} weight={700} fontFamily={2}>
              {description} {year && `(${year})`}
            </Text>
          </Card>
          <Card
            onClick={onClose}
            aria-label="Close"
            radius={0}
            // hoverColor={5}
            // customClass={styles.closeButton}
            style={{ backgroundColor: "transparent" }}
            size={10}
            // borderColor={3}
          >
            <Text size={60} color={3} weight={700} hoverColor={2}>
              X
            </Text>
          </Card>
        </Card>
        <Gutter size={40} />
        <Card
          size={0}
          backgroundColor={1}
          radius={0}
          alignItems="center"
          justifyContent="center"
          customClass={styles.modal}
        >
          <Card size={0} radius={0} fit="fill">
            <CustomImage
              height={60}
              width={90}
              src={
                stills && stills[0]
                  ? stills[0]
                  : "/images/video-placeholder.png"
              }
              alt={title ?? "Video Placeholder"}
              objectFit="cover"
              style={{
                width: "100%",
                height: "66%",
              }}
            />
            {/* <Card
              size={0}
              radius={0}
              fit="fill"
              style={{ width: "100%", height: "66%" }}
              backgroundColor={3}
            >
              <Card>
                <Text size={30} color={2} weight={200} fontFamily={2}>
                  {blurb ?? "Video content is unavailable."}
                </Text>
              </Card>
            </Card> */}
            <Card flexDirection="row" size={0}>
              {stills &&
                stills.map((still, index) => (
                  <CustomImage
                    key={index}
                    // height={20}
                    // width={30}
                    src={still}
                    alt={`${title} Still ${index + 2}`}
                    objectFit="cover"
                    style={{
                      width: "34%",
                      height: "100%",
                    }}
                  />
                ))}
            </Card>
          </Card>
        </Card>
      </Card>
    </div>,
    document.body,
  );
}
