"use client";

import Card from "../components/flexBox/Card";
import Header from "./Header";
import { sections } from "./Portfolio";
import { useState, useRef, useEffect, useCallback } from "react";

export default function Layout() {
  const [activeIndex, setActiveIndex] = useState(0);
  const [scrollProgress, setScrollProgress] = useState(0);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);
  const headerRef = useRef<HTMLDivElement>(null);

  const goTo = useCallback((index: number) => {
    const el = sectionRefs.current[index];
    if (!el) return;
    const headerHeight = headerRef.current?.offsetHeight ?? 0;
    const top = el.getBoundingClientRect().top + window.scrollY - headerHeight;
    window.scrollTo({ top, behavior: "smooth" });
  }, []);

  useEffect(() => {
    let rafId: number;
    let lastScrollTop = -1;

    const tick = () => {
      const scrollTop =
        window.scrollY ||
        document.documentElement.scrollTop ||
        document.body.scrollTop;

      if (scrollTop !== lastScrollTop) {
        lastScrollTop = scrollTop;
        const scrollHeight = Math.max(
          document.documentElement.scrollHeight,
          document.body.scrollHeight,
        );
        const clientHeight = window.innerHeight;
        const maxScroll = scrollHeight - clientHeight;
        setScrollProgress(maxScroll > 0 ? (scrollTop / maxScroll) * 100 : 0);
      }

      rafId = requestAnimationFrame(tick);
    };

    rafId = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(rafId);
  }, []);

  useEffect(() => {
    const handleScroll = () => {
      const scrollTop =
        window.scrollY ||
        document.documentElement.scrollTop ||
        document.body.scrollTop;
      const clientHeight = window.innerHeight;
      const scrollHeight = Math.max(
        document.documentElement.scrollHeight,
        document.body.scrollHeight,
      );

      if (scrollTop + clientHeight >= scrollHeight - 10) {
        setActiveIndex(sections.length - 1);
        return;
      }

      const headerHeight = headerRef.current?.offsetHeight ?? 0;
      const midpoint = headerHeight + (clientHeight - headerHeight) / 2;

      let active = 0;
      sectionRefs.current.forEach((el, index) => {
        if (!el) return;
        if (el.getBoundingClientRect().top <= midpoint) active = index;
      });

      setActiveIndex(active);
    };

    window.addEventListener("scroll", handleScroll, { passive: true });
    document.documentElement.addEventListener("scroll", handleScroll, {
      passive: true,
    });
    return () => {
      window.removeEventListener("scroll", handleScroll);
      document.documentElement.removeEventListener("scroll", handleScroll);
    };
  }, []);

  return (
    <Card
      backgroundColor={1}
      flexDirection="column"
      alignItems="center"
      justifyContent="center"
      style={{ minHeight: "100svh", width: "100svw" }}
      size={0}
    ></Card>
  );
}
