"use client";

import { useState } from "react";
import Card from "../components/flexBox/Card";
import CustomImage from "../components/images/CustomImage";
import Text from "../components/text/Text";
import { projectType } from "../siteData/projectData";
import VideoModal from "./Modal";
import useWindowDimensions from "../hooks/GetDimensions";
import StillsModal from "./StillsModal";
import Gutter from "../components/flexBox/Gutter";

const Project = ({
  title,
  image,
  link,
  description,
  blurb,
  year,
  index,
  stills,
}: projectType) => {
  const [play, setPlay] = useState(false);
  const [hovered, setHovered] = useState(false);

  const { width } = useWindowDimensions();
  const isVerySmall = !!width && width < 500;

  return (
    <>
      <Card
        backgroundColor={2}
        size={0}
        onClick={() => (link || blurb) && setPlay(true)}
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
        hoverColor={3}
        flexDirection={isVerySmall ? "column-reverse" : "row-reverse"}
        justifyContent="flex-end"
        alignItems={isVerySmall ? "flex-start" : "center"}
        // height={50}
        fit="fill"
        style={{ maxWidth: "750px" }}
      >
        {/* Text Section */}
        <Card flexDirection="row" alignItems="center" gap={10} size={10}>
          {/* <Gutter size={isVerySmall ? 10 : 0} horizontal /> */}
          <Card
            size={0}
            backgroundColor={0}
            alignItems="center"
            gap={0}
            flexDirection="row"
          >
            <Gutter size={isVerySmall ? 20 : 0} horizontal />
            <Text color={2} weight={100} size={30} fontFamily={2}>
              {index !== undefined ? index + 1 : ""}
            </Text>
          </Card>
          <Card gap={10}>
            <Text
              color={3}
              weight={800}
              size={60}
              style={{ lineHeight: 1, textAlign: "left" }}
              fontFamily={2}
            >
              {title}
            </Text>
            <Text
              color={2}
              weight={200}
              size={30}
              hoverColor={3}
              style={{ lineHeight: 1, textAlign: "left" }}
              fontFamily={2}
            >
              {description} ({year})
            </Text>
            {/* <Text color={3} weight={200} size={15} hoverColor={3}>
              {year}
            </Text> */}
          </Card>
        </Card>
        {/* End Text Section */}
        {/* Image Section */}
        <Card
          style={{
            position: "relative",
          }}
          size={isVerySmall ? 20 : 40}
        >
          <CustomImage
            src={image ?? "/images/portfolio.png"}
            alt={title ?? "Project Image"}
            objectFit="cover"
            height={isVerySmall ? 80 : 50}
            width={isVerySmall ? undefined : 90}
            style={{
              width: isVerySmall ? "100%" : undefined,
              height: isVerySmall ? "auto" : undefined,
              zIndex: 0,
              flexGrow: 1,
              filter: hovered || play ? "brightness(70%)" : "brightness(100%)",
              transition: "all .5s ease",
            }}
          />
          <Text
            color={hovered ? 3 : 0}
            weight={600}
            size={80}
            style={{
              position: "absolute",
              top: "50%",
              left: "50%",
              transform: "translate(-50%, -50%)",
              zIndex: 1,
              transition: "all .5s ease",
            }}
          >
            {link ? "▶︎" : "See More"}
          </Text>
        </Card>
      </Card>
      {link ? (
        <VideoModal
          src={link}
          isOpen={play}
          onClose={() => setPlay(false)}
          blurb={blurb}
          description={description}
          year={year}
          title={title}
        />
      ) : blurb ? (
        <StillsModal
          src={image}
          isOpen={play}
          onClose={() => setPlay(false)}
          blurb={blurb}
          description={description}
          year={year}
          title={title}
          stills={stills}
        />
      ) : null}
    </>
  );
};

export default Project;
